<?php use App\Controllers\ModuleController as M; use App\Services\AssetService; ?>
<div class="page-header"><h1 class="page-title"><?= e($a['asset_code']) ?> · <?= e($a['name']) ?></h1><div><?= M::link('/assets','ทะเบียนอุปกรณ์') ?><?php if(can('assets.update',(int)$a['hotel_id'])): ?><?= M::link('/assets/'.$a['id'].'/edit','แก้ไข') ?><?php endif ?><?php if(can('tickets.create',(int)$a['hotel_id'])): ?><?= M::link('/tickets/create?asset_id='.$a['id'],'แจ้งซ่อม') ?><?php endif ?></div></div>
<?php if($a['image_path']): ?><img class="img-fluid rounded mb-3" style="max-height:360px" src="<?= e(url('/assets/'.$a['id'].'/image')) ?>" alt="<?= e($a['name']) ?>"><?php endif ?>
<div class="card mb-3"><div class="card-body"><dl class="row"><?php foreach(['brand'=>'ยี่ห้อ','model'=>'รุ่น','serial_no'=>'หมายเลขเครื่อง','status'=>'สถานะ','asset_condition'=>'สภาพ','purchase_date'=>'วันที่ซื้อ','warranty_end'=>'ประกันสิ้นสุด','notes'=>'หมายเหตุ'] as $k=>$v): ?><dt class="col-sm-3"><?= e($v) ?></dt><dd class="col-sm-9"><?= e($a[$k]??'—') ?></dd><?php endforeach ?></dl><?php if($cost): ?><strong>ค่าบำรุงรักษาที่อนุมัติ: <?= e(money($cost['total'])) ?> บาท</strong><?php endif ?></div></div>
<?php if(can('assets.update',(int)$a['hotel_id'])): ?><?= $this->partial('shared/form',['title'=>'เปลี่ยนสถานะ','action'=>'/assets/'.$a['id'].'/status','fields'=>['status'=>['สถานะ','select',AssetService::STATUSES,true],'reason'=>['เหตุผล','text',[],true]],'values'=>[],'notice'=>'']) ?>
<form method="post" enctype="multipart/form-data" action="<?= e(url('/assets/'.$a['id'].'/attachments')) ?>" class="card card-body my-3"><?= csrf_field() ?><label class="form-label">คู่มือ / เอกสาร / รูปภาพ<input type="file" class="form-control" name="files[]" multiple required accept="image/jpeg,image/png,image/webp,application/pdf"></label><button class="btn btn-primary">แนบไฟล์</button></form><?php endif ?>
<h2 class="h5">เอกสารแนบ</h2><?php foreach($attachments as $f): ?><p><?= M::link('/assets/'.$a['id'].'/attachments/'.$f['id'],$f['original_name']) ?></p><?php endforeach ?>
<h2 class="h5 mt-4">ใบงานซ่อม</h2><?php foreach($tickets as $t): ?><p><?= M::link('/tickets/'.$t['id'],$t['ticket_no']) ?> <?= e($t['title']) ?> · <?= e($t['status']) ?></p><?php endforeach ?>
<h2 class="h5 mt-4">ประวัติอุปกรณ์</h2><ul class="list-group"><?php foreach($history as $h): ?><li class="list-group-item"><?= e(dt($h['created_at'])) ?> · <?= e($h['description']) ?></li><?php endforeach ?></ul>
